interface CertificateCardProps {
  name: string;
  issueDate: string;
  expiryDate: string;
  credentialUrl?: string;
}

export default function CertificateCard({ name, issueDate, expiryDate, credentialUrl }: CertificateCardProps) {
  return (
    <div className="card">
      <h4 className="text-base font-semibold text-fg">{name}</h4>
      <p className="text-fg-dim text-sm mt-1">{issueDate} &ndash; {expiryDate}</p>
      {credentialUrl && (
        <a
          href={credentialUrl}
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex items-center gap-1.5 text-sm text-accent hover:text-accent-hover mt-2 transition-colors"
        >
          View Credential
        </a>
      )}
    </div>
  );
}
