import { calculateDuration, formatDate } from '../../data/experience';

interface ExperienceCardProps {
  id: string;
  title: string;
  company: string;
  startDate: string;
  endDate?: string;
  location: string;
  description: string;
  skills?: string[];
}

export default function ExperienceCard({ title, company, startDate, endDate, location, description, skills }: ExperienceCardProps) {
  const duration = calculateDuration(startDate, endDate);
  const startFormatted = formatDate(startDate);
  const endFormatted = endDate ? formatDate(endDate) : 'Present';

  return (
    <div className="card">
      <div className="flex flex-col sm:flex-row sm:justify-between sm:items-start gap-1 sm:gap-4 mb-4">
        <div>
          <h3 className="text-lg font-semibold text-fg">{title}</h3>
          <p className="text-fg-muted text-sm">{company}</p>
          <p className="text-fg-dim text-xs mt-0.5">{location}</p>
        </div>
        <div className="text-sm text-right sm:text-right shrink-0">
          <div className="text-accent font-medium">{duration}</div>
          <div className="text-fg-dim text-xs mt-0.5">{startFormatted} &ndash; {endFormatted}</div>
        </div>
      </div>
      <p className="text-fg-muted text-sm leading-relaxed mb-4">{description}</p>
      {skills && skills.length > 0 && (
        <div className="flex gap-1.5 flex-wrap">
          {skills.map((skill) => (
            <span key={skill} className="tech-badge">{skill}</span>
          ))}
        </div>
      )}
    </div>
  );
}
